<script setup lang="ts">
import { computed, ref } from 'vue'
import { calculateLogisticsFee, logisticsCarriers, logisticsChannels, logisticsCountries, logisticsRules, type LogisticsRule } from '@/data/logistics'

const tabs = ['物流商', '物流渠道', '运费规则', '国家区域', '重量限制', '运费试算'] as const
type Tab = typeof tabs[number]
const activeTab = ref<Tab>('运费规则')
const search = ref('')
const selectedRule = ref<LogisticsRule | null>(null)
const calcRuleId = ref(logisticsRules.find(rule => rule.priceRowCount > 0)?.id ?? 0)
const calcCountry = ref('')
const calcWeight = ref(0.5)
const calcWeightG = ref(Math.round(calcWeight.value * 1000))
const grams = (weightKg: number) => Math.ceil(Math.max(0, weightKg) * 1000)
const weightRangeG = (fromKg: number, toKg: number) => `${grams(fromKg)}–${grams(toKg)} g`
const filteredRules = computed(() => {
  const query = search.value.trim().toLowerCase()
  return query ? logisticsRules.filter(rule => [rule.name, rule.englishName, rule.type, ...rule.relations.flatMap(item => [item.carrier, item.channel, item.channelCode])].some(value => value.toLowerCase().includes(query))) : logisticsRules
})
const currentRule = computed(() => logisticsRules.find(rule => rule.id === calcRuleId.value) ?? logisticsRules[0])
const currentCountries = computed(() => [...new Set(currentRule.value.prices.map(row => row.areaName))].sort((a, b) => a.localeCompare(b, 'zh-CN')))
const calcResult = computed(() => currentRule.value && calcCountry.value ? calculateLogisticsFee(currentRule.value, calcCountry.value, Number(calcWeight.value)) : null)
function selectCalcRule() { calcCountry.value = currentCountries.value[0] ?? '' }
function syncCalcWeight() {
  calcWeightG.value = Math.ceil(Math.max(0, Number(calcWeightG.value) || 0))
  calcWeight.value = calcWeightG.value / 1000
}
selectCalcRule()
</script>

<template>
  <div class="logistics-app">
    <header class="topbar">
      <RouterLink class="brand" to="/quotation"><b>M</b><span><strong>米莱诺报价</strong><small>MILANO PRICING ERP</small></span></RouterLink>
      <nav><RouterLink to="/quotation">我的报价</RouterLink><RouterLink to="/quotation/products">采购</RouterLink><RouterLink to="/quotation/suppliers">供应商</RouterLink><RouterLink class="active" to="/quotation/logistics">物流</RouterLink><RouterLink to="/quotation/members">财务</RouterLink><RouterLink to="/quotation/my-records">我的报价记录</RouterLink><RouterLink to="/quotation/records">公司报价记录</RouterLink></nav>
      <div class="source">数据源：速猫 ERP<small>同步快照 2026-08-06</small></div>
    </header>
    <main>
      <section class="heading"><div><p>LOGISTICS CONFIGURATION</p><h1>物流规则</h1><span>已迁移速猫中的物流商、渠道、国家区域、重量段和完整计费参数。</span></div><div class="summary"><b>66</b><span>运费规则</span><b>{{ logisticsCarriers.length }}</b><span>物流商</span><b>1,626</b><span>国家区域</span><b>3,241</b><span>价格分段</span></div></section>
      <section class="tabs"><button v-for="tab in tabs" :key="tab" :class="{ active: activeTab === tab }" @click="activeTab = tab">{{ tab }}</button></section>

      <section v-if="activeTab === '运费规则'" class="panel">
        <div class="toolbar"><input v-model="search" placeholder="搜索规则、物流商、渠道或编码"><span>共 {{ filteredRules.length }} 条</span></div>
        <div class="table-wrap"><table><thead><tr><th>规则名称</th><th>物流商 / 渠道</th><th>类型</th><th>国家区域</th><th>价格分段</th><th>币种</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="rule in filteredRules" :key="rule.id"><td><b>{{ rule.name }}</b><small>{{ rule.englishName || `速猫 ID ${rule.id}` }}</small></td><td><b>{{ rule.relations[0]?.carrier || '-' }}</b><small>{{ rule.relations[0]?.channel || '未关联渠道' }} · {{ rule.relations[0]?.channelCode || '-' }}</small></td><td><span class="tag">{{ rule.type }}</span></td><td>{{ rule.areaCount }}</td><td>{{ rule.priceRowCount }}</td><td>{{ rule.currency }}</td><td><em>{{ rule.status }}</em></td><td><button class="link" @click="selectedRule = rule">查看详情</button></td></tr></tbody></table></div>
      </section>
      <section v-else-if="activeTab === '物流商'" class="panel cards"><article v-for="carrier in logisticsCarriers" :key="carrier"><i>{{ carrier.slice(0, 1) }}</i><div><b>{{ carrier }}</b><span>{{ logisticsChannels.filter(item => item.carrier === carrier).length }} 个渠道</span></div></article></section>
      <section v-else-if="activeTab === '物流渠道'" class="panel"><div class="table-wrap"><table><thead><tr><th>物流商</th><th>渠道</th><th>渠道编码</th><th>关联运费规则</th></tr></thead><tbody><tr v-for="channel in logisticsChannels" :key="`${channel.ruleId}-${channel.channelCode}`"><td>{{ channel.carrier }}</td><td><b>{{ channel.channel }}</b></td><td><code>{{ channel.channelCode }}</code></td><td>{{ channel.ruleName }}</td></tr></tbody></table></div></section>
      <section v-else-if="activeTab === '国家区域'" class="panel country-grid"><article v-for="country in logisticsCountries" :key="country.code || country.name"><b>{{ country.name }}</b><span>{{ country.code || '—' }}</span><small>{{ logisticsRules.filter(rule => rule.prices.some(price => price.areaName === country.name)).length }} 条可用规则</small></article></section>
      <section v-else-if="activeTab === '重量限制'" class="panel"><div class="table-wrap"><table><thead><tr><th>规则</th><th>最小起始重量</th><th>最大截止重量</th><th>计泡系数</th><th>尺寸限制</th></tr></thead><tbody><tr v-for="rule in logisticsRules.filter(item => item.prices.length)" :key="rule.id"><td><b>{{ rule.name }}</b></td><td>{{ grams(Math.min(...rule.prices.map(row => row.weightFromKg))) }} g</td><td>{{ grams(Math.max(...rule.prices.map(row => row.weightToKg))) }} g</td><td>{{ [...new Set(rule.prices.map(row => row.volumeDivisor).filter(Boolean))].join(' / ') || '-' }}</td><td>{{ Math.max(...rule.prices.map(row => row.maxSideCm)) || '-' }} cm</td></tr></tbody></table></div></section>
      <section v-else class="calculator"><div class="calc-form"><p>FREIGHT CALCULATOR</p><h2>真实规则运费试算</h2><label>运费规则<select v-model.number="calcRuleId" @change="selectCalcRule"><option v-for="rule in logisticsRules.filter(item => item.priceRowCount)" :key="rule.id" :value="rule.id">{{ rule.name }}</option></select></label><label>目的国家 / 区域<select v-model="calcCountry"><option v-for="country in currentCountries" :key="country">{{ country }}</option></select></label><label>计费重量（g）<input v-model.number="calcWeightG" type="number" min="1" step="1" @input="syncCalcWeight"></label></div><div class="calc-result"><small>试算结果 CNY</small><strong v-if="calcResult">¥ {{ calcResult.total.toFixed(2) }}</strong><strong v-else>暂无匹配价格</strong><template v-if="calcResult"><p><span>计费区间</span><b>{{ weightRangeG(calcResult.price.weightFromKg, calcResult.price.weightToKg) }}</b></p><p><span>每 1000g 运费</span><b>¥ {{ calcResult.price.pricePerKg }}</b></p><p><span>挂号费</span><b>¥ {{ calcResult.price.registrationFee }}</b></p><p v-if="calcResult.surcharge"><span>附加费</span><b>¥ {{ calcResult.surcharge.toFixed(2) }}</b></p><p><span>预计时效</span><b>{{ calcResult.price.etaMinDays }}–{{ calcResult.price.etaMaxDays }} 天</b></p></template></div></section>
    </main>
    <div v-if="selectedRule" class="mask" @click.self="selectedRule = null"><aside><button class="close" @click="selectedRule = null">×</button><small>SUMAO RULE #{{ selectedRule.id }}</small><h2>{{ selectedRule.name }}</h2><div class="detail-stats"><span><b>{{ selectedRule.areaCount }}</b>国家区域</span><span><b>{{ selectedRule.priceRowCount }}</b>价格分段</span><span><b>{{ selectedRule.type }}</b>规则类型</span></div><dl><div><dt>物流商</dt><dd>{{ selectedRule.relations[0]?.carrier || '-' }}</dd></div><div><dt>渠道</dt><dd>{{ selectedRule.relations[0]?.channel || '-' }}</dd></div><div><dt>渠道编码</dt><dd>{{ selectedRule.relations[0]?.channelCode || '-' }}</dd></div><div><dt>发布状态</dt><dd>{{ selectedRule.published }}</dd></div><div><dt>更新时间</dt><dd>{{ selectedRule.dates }}</dd></div></dl><h3>价格示例（前 12 条）</h3><div class="mini"><p v-for="(price, index) in selectedRule.prices.slice(0, 12)" :key="index"><b>{{ price.areaName }}</b><span>{{ weightRangeG(price.weightFromKg, price.weightToKg) }}</span><span>¥{{ price.pricePerKg }}/1000g + ¥{{ price.registrationFee }}</span></p></div></aside></div>
  </div>
</template>

<style scoped>
:global(body){margin:0}.logistics-app{--orange:#ff9d16;--ink:#17212b;--muted:#7a858f;--line:#e3e7ea;min-height:100vh;background:#f4f6f8;color:var(--ink);font-family:Inter,"PingFang SC","Microsoft YaHei",sans-serif}.topbar{height:68px;display:flex;align-items:center;padding:0 4vw;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:20}.brand{display:flex;align-items:center;gap:10px;margin-right:48px;color:inherit;text-decoration:none}.brand>b{width:39px;height:39px;display:grid;place-items:center;background:var(--orange);border-radius:10px}.brand span,.brand small,.topbar small,td small{display:block}.brand small{font-size:8px;letter-spacing:.13em;color:#969da4}.topbar nav{display:flex;gap:28px;height:100%}.topbar nav a{display:flex;align-items:center;position:relative;color:#66717c;text-decoration:none;font-size:13px}.topbar nav a.active{color:var(--ink);font-weight:800}.topbar nav a.active:after{content:"";position:absolute;left:0;right:0;bottom:0;height:3px;background:var(--orange)}.source{margin-left:auto;text-align:right;font-size:11px}.source small{color:#969da4}main{width:min(1500px,94vw);margin:auto;padding:34px 0 70px}.heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:22px}.heading p,.calc-form p{margin:0 0 7px;color:#d77b00;font-size:10px;font-weight:900;letter-spacing:.18em}.heading h1{margin:0 0 7px;font-size:30px}.heading>div>span{color:var(--muted);font-size:13px}.summary{display:grid;grid-template-columns:repeat(4,auto);gap:3px 22px;align-items:end}.summary b{font-size:24px}.summary span{font-size:10px;color:var(--muted)}.tabs{display:flex;gap:3px;padding:5px;background:#e9edf0;border-radius:9px}.tabs button{flex:1;height:39px;border:0;border-radius:6px;background:transparent;color:#65717b}.tabs button.active{background:#fff;color:#171f26;font-weight:850;box-shadow:0 2px 10px #21303e12}.panel{margin-top:15px;background:#fff;border:1px solid var(--line);border-radius:9px;overflow:hidden}.toolbar{height:57px;display:flex;align-items:center;gap:16px;padding:0 16px;border-bottom:1px solid var(--line)}.toolbar input{width:330px;height:35px;border:1px solid #dce1e5;border-radius:6px;padding:0 11px}.toolbar span{margin-left:auto;color:var(--muted);font-size:11px}.table-wrap{overflow:auto;max-height:650px}table{width:100%;border-collapse:collapse;font-size:11px}th{text-align:left;padding:13px 14px;background:#fafbfc;color:#6f7982;position:sticky;top:0}td{padding:13px 14px;border-top:1px solid #edf0f2}td b{font-size:12px}td small{margin-top:4px;color:#929ba3}em{padding:4px 8px;border-radius:10px;background:#e9f7ef;color:#218453;font-style:normal}.tag{padding:4px 7px;border-radius:4px;background:#f0f3f5}.link{border:0;background:none;color:#c87500}.cards,.country-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;padding:16px}.cards article,.country-grid article{display:flex;align-items:center;gap:11px;padding:15px;border:1px solid var(--line);border-radius:7px}.cards i{width:34px;height:34px;display:grid;place-items:center;border-radius:8px;background:#fff1d8;color:#b96800;font-style:normal;font-weight:900}.cards span,.country-grid small{display:block;color:var(--muted);font-size:10px}.country-grid article{display:grid;grid-template-columns:1fr auto}.country-grid span{color:#d47a00}.country-grid small{grid-column:1/-1}.calculator{display:grid;grid-template-columns:1fr 360px;margin-top:15px;background:#fff;border:1px solid var(--line);border-radius:10px;overflow:hidden}.calc-form{padding:30px}.calc-form h2{margin:0 0 24px}.calc-form label{display:grid;gap:6px;margin:12px 0;color:var(--muted);font-size:10px}.calc-form select,.calc-form input{height:40px;border:1px solid #dce1e5;border-radius:6px;padding:0 10px;background:#fff}.calc-result{padding:30px;background:#1b2630;color:#fff}.calc-result>small{color:#aeb7bf}.calc-result>strong{display:block;margin:10px 0 25px;color:#ffad38;font-size:28px}.calc-result p{display:flex;justify-content:space-betwe